async function loadReadingLibrary(){$('reading-library-view').style.display='block';$('reading-practice-view').style.display='none';$('reading-library-list').innerHTML='<div class="empty">Loading...</div>';try{const d=await jsonFetch('/api/reading/library');readingLibraryItems=d.items||[];renderReadingLibraryList()}catch(e){$('reading-library-list').innerHTML='<div class="empty">Could not load the library.</div>';toast(e.message)}}
function renderReadingLibraryList(){const items=readingLibraryItems.filter(x=>readingLibraryFilter==='all'||x.level===readingLibraryFilter);$('reading-library-list').innerHTML=items.map(x=>`<div class="report" style="text-align:left"><b style="display:block;font-size:14px">📖 ${esc(x.title)}</b><small style="color:var(--muted);text-transform:capitalize">${esc(x.level)} · ${x.minutes} min</small><div class="actions" style="margin-top:10px"><button type="button" class="btn" data-reading-id="${x.id}">Start reading →</button></div></div>`).join('')||'<div class="empty">No readings for this level.</div>';$$('#reading-library-list [data-reading-id]').forEach(b=>b.addEventListener('click',()=>openReadingEntry(b.dataset.readingId)))}
function setReadingFilter(level){readingLibraryFilter=level;$$('#reading-filter-bar .mode').forEach(b=>b.classList.toggle('active',b.dataset.level===level));renderReadingLibraryList()}
async function openReadingEntry(entryId){state.readingEntryId=entryId;$('reading-library-view').style.display='none';$('reading-practice-view').style.display='block';$('reading-text').textContent='Loading reading...';$('reading-time').textContent='';$('reading-answer').value='';$('reading-result').style.display='none';try{const d=await jsonFetch('/api/reading/library/'+entryId);state.reading=d;$('reading-text').textContent=d.texto||'';const words=(d.texto||'').trim().split(/\s+/).filter(Boolean).length;$('reading-time').textContent=words?`⏱ ${Math.max(1,Math.round(words/200))} min read`:''}catch(e){toast(e.message)}}
