async function evaluateReading(){if(!state.reading)return toast('Load a reading first.');const answer=$('reading-answer').value.trim();if(!answer)return toast('Explain what you understood first.');busy('reading-submit',true,'Analyzing...');try{const d=await jsonFetch('/evaluar-lectura',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({texto_original:state.reading.texto,respuesta:answer})});$('r-score').textContent=Math.round(d.puntuacion||0);$('r-accuracy').textContent=Math.round(d.precision||0);$('r-language').textContent=Math.round(d.calidad_ingles||d.gramatica||0);$('r-vocab').textContent=Math.round(d.vocabulario||0);$('r-summary').textContent=d.resumen||'';$('r-good').innerHTML=(d.aciertos||[]).map(x=>`<li>${esc(x)}</li>`).join('');$('r-improve').innerHTML=(d.mejoras||[]).map(x=>`<li>${esc(x)}</li>`).join('');$('r-vocab-list').innerHTML=(d.vocabulario_sugerido||[]).map(x=>`<div class="vocab-item"><b>${esc(x.palabra||x.term||'')}</b><p>${esc(x.significado||x.meaning||'')}</p><button type="button" class="btn vocab-save-btn" style="margin-top:6px;padding:0 8px;min-height:26px;font-size:10px" data-word="${esc(x.palabra||x.term||'')}" data-meaning="${esc(x.significado||x.meaning||'')}">+ Save</button></div>`).join('');$('reading-result').style.display='block';reactToScore(d.puntuacion);renderCoachInsight('reading-coach',[{label:'Accuracy',value:d.precision},{label:'English quality',value:d.calidad_ingles||d.gramatica},{label:'Vocabulary',value:d.vocabulario}],[{label:'🔄 Try a new reading',fn:regenerateReading},{label:'📍 Practice in Learning Path',fn:()=>goToLearningPathFor('reading')}])}catch(e){toast(e.message)}finally{busy('reading-submit',false,'Analyze comprehension')}}
