function addCallMessage(text,who){const wrap=$('call-messages');const div=document.createElement('div');div.className='msg '+(who==='user'?'user':'ai');div.textContent=text;wrap.appendChild(div);wrap.scrollTop=wrap.scrollHeight}
async function callStartTalk(){if(state.callBusy)return;if(!navigator.mediaDevices?.getUserMedia)return toast('Tu navegador no soporta grabación de audio.');try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});let mime='audio/webm';if(window.MediaRecorder&&MediaRecorder.isTypeSupported){if(!MediaRecorder.isTypeSupported(mime)){const alternatives=['audio/webm;codecs=opus','audio/ogg;codecs=opus','audio/mp4'];mime=alternatives.find(x=>MediaRecorder.isTypeSupported(x))||''}}state.callChunks=[];state.callRecorder=new MediaRecorder(stream,mime?{mimeType:mime}:undefined);state.callRecorder.ondataavailable=e=>{if(e.data.size)state.callChunks.push(e.data)};state.callRecorder.onstop=callSendTurn;state.callRecorder.start();$('call-talk-btn').classList.add('recording');$('call-status').textContent='Escuchando... suelta cuando termines'}catch(e){toast('Error de micrófono: '+e.message)}}
function callStopTalk(){$('call-talk-btn').classList.remove('recording');if(state.callRecorder&&state.callRecorder.state!=='inactive'){state.callRecorder.stop();state.callRecorder.stream?.getTracks().forEach(t=>t.stop())}}
async function callSendTurn(){const blob=new Blob(state.callChunks,{type:state.callChunks[0]?.type||'audio/webm'});if(!blob.size){$('call-status').textContent='Mantén presionado el botón para hablar';return}state.callBusy=true;$('call-status').textContent='Transcribiendo...';const fd=new FormData();fd.append('audio',blob,'call.webm');try{const t=await jsonFetch('/api/transcribir-audio',{method:'POST',body:fd});const said=(t.texto||'').trim();if(!said){$('call-status').textContent='No te escuché bien, intenta de nuevo';state.callBusy=false;return}addCallMessage(said,'user');state.callMessages.push({role:'user',content:said});$('call-status').textContent='Palanqueta está pensando...';const d=await jsonFetch('/api/tutor',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mensaje:said,history:state.callMessages.slice(-14),modo:'llamada'})});const reply=d.respuesta||'';addCallMessage(reply,'ai');state.callMessages.push({role:'assistant',content:reply});await callPlayReply(reply)}catch(e){toast(e.message)}finally{$('call-status').textContent='Mantén presionado el botón para hablar';state.callBusy=false}}
async function callPlayReply(text){if(!text)return;$('call-status').textContent='Palanqueta está hablando...';startMascotTalking();try{const r=await authFetch('/api/sintetizar-audio',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({texto:text,voz:'en-US-AvaMultilingualNeural'})});if(!r.ok)throw new Error('voz no disponible');const blob=await r.blob();const url=URL.createObjectURL(blob);const audio=new Audio(url);await new Promise(res=>{audio.onended=res;audio.onerror=res;audio.play()});URL.revokeObjectURL(url)}catch(e){speak(text)}finally{stopMascotTalking()}}
async function endCall(){vadStop();if(!state.callMessages||!state.callMessages.length)return toast('Todavía no has hablado con Palanqueta.');callStopTalk();$('call-status').textContent='Generando resumen...';try{const d=await jsonFetch('/api/resumen-llamada',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({history:state.callMessages})});$('call-score-general').textContent=Math.round(d.puntuacion_general||0);$('call-score-fluency').textContent=Math.round(d.fluidez||0);$('call-score-grammar').textContent=Math.round(d.gramatica||0);$('call-score-vocab').textContent=Math.round(d.vocabulario||0);$('call-score-pron').textContent=Math.round(d.pronunciacion_estimada||0);$('call-summary-general').textContent=d.resumen_general||'';$('call-summary-strengths').innerHTML=(d.fortalezas||[]).map(x=>`<li>${esc(x)}</li>`).join('');$('call-summary-errors').innerHTML=(d.errores_comunes||[]).map(x=>`<li>${esc(x)}</li>`).join('');$('call-summary-vocab').innerHTML=(d.vocabulario_recomendado||[]).map(v=>`<div class="vocab-item"><b>${esc(v.palabra||'')}</b><p>${esc(v.significado||'')}</p></div>`).join('');$('call-summary-next').textContent=d.siguiente_paso||'';$('call-summary').style.display='block';state.callMessages=[];$('call-messages').innerHTML='<div class="msg ai">Hi! I\'m Palanqueta. Press and hold the button, say something, and let go when you\'re done.</div>'}catch(e){toast(e.message)}finally{$('call-status').textContent='Mantén presionado el botón para hablar'}}
async function loadDashboard(){loadNextStep();try{const email=(state.user&&state.user.email)||'';const name=state.username||email.split('@')[0]||'there';const hour=new Date().getHours();const greet=hour<12?'Good morning':hour<19?'Good afternoon':'Good evening';$('home-greeting').textContent=`${greet}, ${esc(name)}! 👋`;const d=await jsonFetch('/api/dashboard');$('home-streak').textContent=`🔥 ${d.streak_days} day streak`;$('home-xp').textContent=`⭐ ${d.xp} XP · Level ${d.level}`;$('home-goal-pct').textContent=d.daily_goal_pct+'%';$('home-goal-fill').style.width=d.daily_goal_pct+'%';$('home-week').innerHTML=(d.week||[]).map(w=>`<div class="day-chip${w.active?' active':''}${w.is_today?' today':''}"><div class="dot">${w.active?'🔥':''}</div><small>${esc(w.weekday)}</small></div>`).join('');const labels={speaking:'🗣️ Speaking',listening:'🎧 Listening',reading:'📖 Reading',writing:'✍️ Writing'};$('home-skills').innerHTML=Object.entries(d.skills||{}).map(([k,v])=>`<div class="report" style="--v:${v}%"><b>${v}%</b><small>${labels[k]||k}</small></div>`).join('');try{const a=await jsonFetch('/api/achievements');$('home-achievements').innerHTML=a.achievements.slice(0,4).map(x=>`<div class="report ach-card${x.unlocked?' unlocked':''}"><div class="ach-icon">${x.icon}</div><small style="display:block;margin-top:4px">${esc(x.title)}</small></div>`).join('')}catch(e){}
try{const vd=await jsonFetch('/api/vocabulario/diario');const w=(vd.palabras||[])[0];$('home-vocab-word').innerHTML=w?`<b style="font-size:16px">${esc(w.palabra)}</b><p style="margin:4px 0;color:var(--muted);font-size:12px">${esc(w.significado||'')}</p>${w.ejemplo?`<p style="font-style:italic;font-size:12px">"${esc(w.ejemplo)}"</p>`:''}`:'<div class="empty">No words yet.</div>'}catch(e){$('home-vocab-word').innerHTML='<div class="empty">Could not load today\'s word.</div>'}
try{const vl=await jsonFetch('/api/vocabulario');const pct=vl.total?Math.round(vl.aprendidas/vl.total*100):0;$('home-vocab-stats').innerHTML=`<small style="color:var(--muted)">Your vocabulary</small><div style="font-weight:700;font-size:15px;margin:2px 0">${vl.aprendidas} / ${vl.total} learned</div><div class="bar" style="margin-top:6px"><div class="fill" style="width:${pct}%"></div></div><button type="button" class="btn" id="home-vocab-review-btn" style="margin-top:8px">Review words →</button>`;$('home-vocab-review-btn')?.addEventListener('click',()=>{section('vocabulario');closeSidebar()})}catch(e){}}catch(e){console.error('[DASHBOARD]',e)}}
async function loadAchievements(){try{const d=await jsonFetch('/api/achievements');$('ach-count').textContent=`🏆 ${d.unlocked_count} / ${d.achievements.length} unlocked`;$('ach-list').innerHTML=d.achievements.map(a=>`<div class="report ach-card${a.unlocked?' unlocked':''}"><div class="ach-icon">${a.icon}</div><b style="display:block;margin-top:6px;font-size:13px">${esc(a.title)}</b>${a.unlocked?'<small style="color:var(--success)">✓ Completed</small>':`<div class="bar"><div class="fill" style="width:${a.progress}%"></div></div><small>${a.progress}%</small>`}</div>`).join('')}catch(e){toast(e.message)}}
async function loadVocabDaily(){$('vocab-daily').innerHTML='<div class="empty">Loading...</div>';try{const d=await jsonFetch('/api/vocabulario/diario');$('vocab-daily').innerHTML=d.palabras.map(w=>`<div class="vocab-item" style="margin-bottom:8px"><b>${esc(w.palabra)}</b><p>${esc(w.significado||'')}</p>${w.ejemplo?`<p style="font-style:italic">"${esc(w.ejemplo)}"</p>`:''}<div class="actions" style="justify-content:flex-start;margin-top:6px;gap:6px"><button type="button" class="btn" style="padding:0 8px;min-height:26px;font-size:10px" onclick="playGuideAudio(${JSON.stringify(w.palabra)},this.id||'vocab-refresh')">🔊</button></div></div>`).join('')||'<div class="empty">No words yet.</div>';loadVocabList()}catch(e){$('vocab-daily').innerHTML='<div class="empty">Could not load today\'s words.</div>'}}
async function loadVocabList(){try{const d=await jsonFetch('/api/vocabulario');$('vocab-total').textContent=`📚 ${d.total} words saved`;$('vocab-learned').textContent=`✅ ${d.aprendidas} learned`;$('vocab-list').innerHTML=d.palabras.map(w=>`<div class="history-card"><div class="history-head"><span>${esc(w.palabra)}</span><button type="button" class="btn vocab-toggle-btn" style="padding:0 8px;min-height:24px;font-size:10px" data-id="${w.id}" data-state="${w.aprendida}">${w.aprendida?'✓ Learned':'Mark learned'}</button></div><div class="history-meta"><span>${esc(w.significado||'')}</span><span>${esc(w.origen||'')}</span></div></div>`).join('')||'<div class="empty">No saved words yet.</div>'}catch(e){toast(e.message)}}
let lpState={units:[],currentUnit:null,topics:[],currentTopicId:null,currentTool:null,currentExercise:null,recorder:null,chunks:[],recording:false};
async function loadLearningPath(){$('lp-topics-view').style.display='none';$('lp-units-view').style.display='block';$('lp-units').innerHTML='<div class="empty">Loading...</div>';try{const d=await jsonFetch('/api/learning-path');lpState.units=d.units;$('lp-xp').textContent=`⭐ ${d.xp} XP`;let currentAssigned=false;$('lp-units').innerHTML=d.units.map((u,i)=>{const pct=u.total_topics?Math.round(u.completed_topics/u.total_topics*100):0;const locked=!u.unlocked;const isCurrent=!locked&&!u.completed&&!currentAssigned;if(isCurrent)currentAssigned=true;const state=locked?'locked':(u.completed?'completed':(isCurrent?'current':''));const align=i%2===0?'align-left':'align-right';const connector=i>0?'<div class="lp-connector"></div>':'';const icon=locked?'🔒':(u.completed?'✓':u.icon);return `<div class="lp-node ${align}">${connector}<div class="lp-circle ${state}" ${locked?'':`onclick="openLearningUnit('${u.code}')"`}>${icon}</div><div class="lp-node-label"><b style="display:block;font-size:14px">${esc(u.title)}</b>${locked?`<small style="color:var(--muted)">Requires ${u.xp_required} XP${u.order>1?' + previous unit':''}</small>`:`<small style="color:var(--muted)">${u.completed_topics}/${u.total_topics} lessons${u.completed?' · Completed 🎉':''}</small><div class="bar" style="margin-top:6px;width:140px"><div class="fill" style="width:${pct}%"></div></div>`}</div></div>`}).join('')}catch(e){$('lp-units').innerHTML='<div class="empty">Could not load your learning path.</div>';toast(e.message)}}
function renderLPTopics(){$('lp-topics').innerHTML=lpState.topics.map(t=>`<div class="report" style="text-align:left;cursor:pointer" onclick="openLearningTopic('${t.id}')"><b style="display:block;font-size:13px">${esc(t.title)}</b>${t.completed?'<small style="color:var(--success)">✓ Completed</small>':'<small>Not started</small>'}</div>`).join('')}
async function openLearningUnit(code){try{const d=await jsonFetch('/api/learning-path/'+code);lpState.currentUnit={...d.unit,code};lpState.topics=d.topics;$('lp-units-view').style.display='none';$('lp-topics-view').style.display='block';$('lp-unit-title').textContent=d.unit.icon+' '+d.unit.title;$('lp-unit-desc').textContent=d.unit.description;renderLPTopics();$('lp-tool-picker').style.display='none';$('lp-practice-area').innerHTML=''}catch(e){toast(e.message)}}
function backToLPUnits(){$('lp-topics-view').style.display='none';$('lp-units-view').style.display='block';loadLearningPath()}
function openLearningTopic(topicId){lpState.currentTopicId=topicId;const t=lpState.topics.find(x=>x.id===topicId);$('lp-tool-picker').style.display='block';$('lp-tool-picker-title').textContent=`How do you want to practice "${t.title}"?`;$('lp-practice-area').innerHTML=''}
function markLPTopicDone(){const t=lpState.topics.find(x=>x.id===lpState.currentTopicId);if(t)t.completed=true;renderLPTopics()}
function renderLPProgressBanner(lp){if(!lp)return '';if(lp.newly_completed)return `<div class="notice" style="margin-top:10px;color:var(--success)">🎉 Topic completed! +30 XP${lp.unit_completed?' · 🏆 Unit completed!':''}</div>`;if(lp.passed)return '<div class="notice" style="margin-top:10px">✓ Already completed.</div>';return '<div class="notice" style="margin-top:10px">Keep practicing — you need at least 60% to complete this topic.</div>'}
async function startLearningPractice(tool){lpState.currentTool=tool;$('lp-practice-area').innerHTML='<div class="empty">Preparing your exercise...</div>';try{const d=await jsonFetch('/api/learning-path/practice',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({unit_code:lpState.currentUnit.code,topic_id:lpState.currentTopicId,tool})});lpState.currentExercise=d;renderLearningPractice(tool,d)}catch(e){$('lp-practice-area').innerHTML='';toast(e.message)}}
function renderLearningPractice(tool,d){if(tool==='pronunciation'){$('lp-practice-area').innerHTML=`<div class="card"><p style="font-size:11px;color:var(--muted)">Say this out loud:</p><p style="font-size:18px;font-weight:600;margin:8px 0">${esc(d.texto)}</p><div class="actions" style="justify-content:flex-start"><button type="button" class="btn primary" id="lp-record-btn" onclick="toggleLPRecording()">Start recording</button></div><div id="lp-practice-result"></div></div>`}else if(tool==='writing'){$('lp-practice-area').innerHTML=`<div class="card"><p style="font-size:11px;color:var(--muted)">Writing challenge:</p><p style="font-size:14px;font-weight:600;margin:8px 0">${esc(d.prompt)}</p><textarea id="lp-writing-input" placeholder="Write in English..."></textarea><div class="actions" style="margin-top:8px"><button type="button" class="btn primary" onclick="submitLPWriting()">Analyze writing</button></div><div id="lp-practice-result"></div></div>`}else if(tool==='reading'){$('lp-practice-area').innerHTML=`<div class="card"><p style="font-size:11px;color:var(--muted)">${esc(d.titulo||'Reading')}</p><div class="reading" style="margin:8px 0">${esc(d.texto)}</div><label class="field-label">Explain what you understood, in English</label><textarea id="lp-reading-input" placeholder="Write your explanation..."></textarea><div class="actions" style="margin-top:8px"><button type="button" class="btn primary" onclick="submitLPReading()">Submit</button></div><div id="lp-practice-result"></div></div>`}else if(tool==='dictado'){$('lp-practice-area').innerHTML=`<div class="card"><p style="font-size:11px;color:var(--muted)">Listen carefully, then type what you hear.</p><div class="actions" style="justify-content:flex-start"><button type="button" class="btn" onclick="speak(lpState.currentExercise.texto,.9)">🔊 Play</button></div><textarea id="lp-dictation-input" placeholder="Type what you heard..." style="margin-top:8px"></textarea><div class="actions" style="margin-top:8px"><button type="button" class="btn primary" onclick="submitLPDictation()">Submit</button></div><div id="lp-practice-result"></div></div>`}}
function toggleLPRecording(){const b=$('lp-record-btn');if(lpState.recording){lpState.recording=false;b.textContent='Analyzing...';b.disabled=true;try{lpState.recorder.stop();lpState.recorder.stream?.getTracks().forEach(t=>t.stop())}catch(e){toast('Recording could not be stopped.')}}else{if(!navigator.mediaDevices?.getUserMedia)return toast('Your browser does not support microphone recording.');navigator.mediaDevices.getUserMedia({audio:true}).then(stream=>{let mime='audio/webm';if(window.MediaRecorder&&MediaRecorder.isTypeSupported&&!MediaRecorder.isTypeSupported(mime)){const alts=['audio/webm;codecs=opus','audio/ogg;codecs=opus','audio/mp4'];mime=alts.find(x=>MediaRecorder.isTypeSupported(x))||''}lpState.chunks=[];lpState.recorder=new MediaRecorder(stream,mime?{mimeType:mime}:undefined);lpState.recorder.ondataavailable=e=>{if(e.data.size)lpState.chunks.push(e.data)};lpState.recorder.onstop=sendLPRecording;lpState.recorder.start();lpState.recording=true;b.textContent='Recording... click to stop'}).catch(e=>toast('Microphone error: '+e.message))}}
async function sendLPRecording(){const blob=new Blob(lpState.chunks,{type:lpState.chunks[0]?.type||'audio/webm'});const fd=new FormData();fd.append('audio',blob,'recording.webm');fd.append('frase_esperada',lpState.currentExercise.texto||'');fd.append('unit_code',lpState.currentUnit.code);fd.append('topic_id',lpState.currentTopicId);try{const d=await jsonFetch('/analizar-audio-real',{method:'POST',body:fd});$('lp-practice-result').innerHTML=`<div class="report-grid" style="margin-top:10px"><div class="report"><b>${Math.round(d.puntuacion_global||0)}</b><small>Overall</small></div><div class="report"><b>${Math.round(d.precision||0)}</b><small>Accuracy</small></div><div class="report"><b>${Math.round(d.fluidez||0)}</b><small>Fluency</small></div></div>${renderLPProgressBanner(d.learning_path)}`;if(d.learning_path&&d.learning_path.newly_completed)markLPTopicDone()}catch(e){toast(e.message)}finally{const b=$('lp-record-btn');if(b){b.textContent='Start recording';b.disabled=false}}}
async function submitLPWriting(){const text=$('lp-writing-input').value.trim();if(!text)return toast('Write something first.');try{const d=await jsonFetch('/analizar-escritura',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({texto:text,unit_code:lpState.currentUnit.code,topic_id:lpState.currentTopicId})});$('lp-practice-result').innerHTML=`<div class="report-grid" style="margin-top:10px"><div class="report"><b>${Math.round(d.puntuacion||0)}</b><small>Overall</small></div><div class="report"><b>${Math.round(d.gramatica||0)}</b><small>Grammar</small></div><div class="report"><b>${Math.round(d.vocabulario||0)}</b><small>Vocabulary</small></div></div>${renderLPProgressBanner(d.learning_path)}`;if(d.learning_path&&d.learning_path.newly_completed)markLPTopicDone()}catch(e){toast(e.message)}}
async function submitLPReading(){const answer=$('lp-reading-input').value.trim();if(!answer)return toast('Explain what you understood first.');try{const d=await jsonFetch('/evaluar-lectura',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({texto_original:lpState.currentExercise.texto,respuesta:answer,unit_code:lpState.currentUnit.code,topic_id:lpState.currentTopicId})});$('lp-practice-result').innerHTML=`<div class="report-grid" style="margin-top:10px"><div class="report"><b>${Math.round(d.puntuacion||0)}</b><small>Overall</small></div><div class="report"><b>${Math.round(d.claridad||0)}</b><small>Clarity</small></div><div class="report"><b>${Math.round(d.vocabulario||0)}</b><small>Vocabulary</small></div></div>${renderLPProgressBanner(d.learning_path)}`;if(d.learning_path&&d.learning_path.newly_completed)markLPTopicDone()}catch(e){toast(e.message)}}
async function submitLPDictation(){const answer=$('lp-dictation-input').value.trim();if(!answer)return toast('Type what you heard first.');try{const d=await jsonFetch('/evaluar-dictado',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({texto_original:lpState.currentExercise.texto,respuesta:answer,unit_code:lpState.currentUnit.code,topic_id:lpState.currentTopicId})});$('lp-practice-result').innerHTML=`<div class="report-grid" style="margin-top:10px"><div class="report"><b>${Math.round(d.puntuacion||0)}</b><small>Score</small></div><div class="report"><b>${d.palabras_correctas??0}</b><small>Correct words</small></div><div class="report"><b>${d.diferencias??0}</b><small>Differences</small></div></div>${renderLPProgressBanner(d.learning_path)}`;if(d.learning_path&&d.learning_path.newly_completed)markLPTopicDone()}catch(e){toast(e.message)}}
async function saveVocabWord(palabra,significado,origen){try{await jsonFetch('/api/vocabulario/guardar',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({palabra,significado,origen})});toast('Saved to your vocabulary.');loadVocabList()}catch(e){toast(e.message)}}
async function toggleVocabLearned(id,current){try{await jsonFetch('/api/vocabulario/marcar',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,aprendida:!current})});loadVocabList()}catch(e){toast(e.message)}}
const FRAME_GRADIENTS={gold:'linear-gradient(135deg,#f5c542,#ffb37a)',fire:'linear-gradient(135deg,#ff6b4a,#ff3d6e)',ocean:'linear-gradient(135deg,#4ad0ff,#7180ff)'};
function avatarMarkup(url,initials,frameGradient){const inner=url?`<img src="${esc(url)}" alt="" style="width:100%;height:100%;object-fit:cover;border-radius:50%">`:esc(initials);if(!frameGradient)return inner;return `<div style="width:100%;height:100%;border-radius:50%;padding:3px;background:${frameGradient};display:flex;align-items:center;justify-content:center;box-sizing:border-box"><div style="width:100%;height:100%;border-radius:50%;overflow:hidden;background:var(--bg);display:flex;align-items:center;justify-content:center">${inner}</div></div>`}
function applyProfileIdentity(user,d){const u=(d&&d.user)||{};state.username=u.username||'';state.avatarFrame=u.avatar_frame||'';const name=u.username||user.email||'Signed in';const initials=(u.username||user.email||'T').trim().slice(0,2).toUpperCase();const frameGrad=FRAME_GRADIENTS[u.avatar_frame]||null;$('user-display').textContent=name;$('side-email').textContent=u.username||user.email||'Student';$('side-avatar').innerHTML=avatarMarkup(u.avatar_url,initials,frameGrad);$('profile-avatar-preview').innerHTML=avatarMarkup(u.avatar_url,initials,frameGrad);$('profile-username').value=u.username||''}
async function saveUsername(){const name=$('profile-username').value.trim();if(name.length<2)return toast('Escribe al menos 2 caracteres.');busy('profile-username-save',true,'Saving...');try{await jsonFetch('/api/perfil',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:name})});$('user-display').textContent=name;$('side-email').textContent=name;toast('Nombre actualizado.')}catch(e){toast(e.message)}finally{busy('profile-username-save',false,'Save')}}
async function uploadAvatar(file){if(!file)return;if(file.size>4*1024*1024)return toast('La imagen no debe pesar más de 4 MB.');const fd=new FormData();fd.append('avatar',file);busy('profile-avatar-btn',true,'Uploading...');try{const d=await jsonFetch('/api/perfil/avatar',{method:'POST',body:fd});const frameGrad=FRAME_GRADIENTS[state.avatarFrame]||null;$('profile-avatar-preview').innerHTML=avatarMarkup(d.avatar_url,'T',frameGrad);$('side-avatar').innerHTML=avatarMarkup(d.avatar_url,'T',frameGrad);toast('Foto actualizada.')}catch(e){toast(e.message)}finally{busy('profile-avatar-btn',false,'Upload photo')}}
function renderAccountInfo(user,d){$('acc-email').textContent=user.email||'-';const miembro=d.user&&d.user.miembro_desde?new Date(d.user.miembro_desde).toLocaleDateString():'-';$('acc-miembro').textContent=miembro;if(d.en_prueba){$('acc-plan').textContent='Prueba gratis';$('acc-plan').style.color='var(--warning)';$('acc-dias').textContent=d.trial_dias_restantes+' día(s)';$('acc-detalle').textContent='Estás en tu período de prueba gratuita. Al terminar, renueva para seguir practicando.';$('acc-renovar').style.display='none'}else if(d.is_subscribed){$('acc-plan').textContent='Activa';$('acc-plan').style.color='var(--success)';$('acc-dias').textContent='—';$('acc-detalle').textContent='Tu suscripción está activa. ¡Sigue practicando!';$('acc-renovar').style.display='none'}else{$('acc-plan').textContent='Vencida';$('acc-plan').style.color='var(--danger)';$('acc-dias').textContent='0 días';$('acc-detalle').textContent='Tu prueba o suscripción terminó. Renueva por $79 MXN/mes para seguir con acceso.';$('acc-renovar').style.display='inline-block';$('acc-renovar').href='https://wa.me/529911093870?text=Hola%2C%20ya%20hice%20mi%20pago%20de%20%2479%20MXN%2C%20aqui%20esta%20mi%20comprobante%3A'}}
async function enviarSoporte(){const tipo=$('soporte-tipo').value;const texto=$('soporte-texto').value.trim();if(!texto)return toast('Escribe tu mensaje antes de enviar.');busy('soporte-enviar',true,'Enviando...');try{await jsonFetch('/api/soporte',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({tipo,mensaje:texto})});$('soporte-texto').value='';$('soporte-confirmacion').style.display='block';setTimeout(()=>$('soporte-confirmacion').style.display='none',5000)}catch(e){toast(e.message)}finally{busy('soporte-enviar',false,'Enviar mensaje')}}
function addTutorMessage(text,who){const wrap=$('tutor-messages');const div=document.createElement('div');div.className='msg '+(who==='user'?'user':'ai');div.textContent=text;wrap.appendChild(div);wrap.scrollTop=wrap.scrollHeight}
let tutorCategory='conversation';
const TUTOR_OPENERS={conversation:'Hi! I\'m Palanqueta, your English tutor. Tell me something about your day.',grammar:'Let\'s work on grammar today! Tell me about something you did last weekend — I\'ll help you get the tenses just right.',vocabulary:'Let\'s grow your vocabulary! Tell me about a hobby you enjoy, and I\'ll introduce some useful new words as we talk.',pronunciation:'Let\'s focus on pronunciation. Try saying a short sentence about yourself, and I\'ll give you tips on how it should sound.',free:'Free talk! Tell me about anything on your mind — no particular topic, just practice speaking freely.'};
function setTutorCategory(cat){tutorCategory=cat;$$('#tutor-category-bar .mode').forEach(b=>b.classList.toggle('active',b.dataset.cat===cat));$('tutor-messages').innerHTML=`<div class="msg ai">${esc(TUTOR_OPENERS[cat]||TUTOR_OPENERS.conversation)}</div>`}
async function tutorSend(text){const value=(text??$('tutor-input').value).trim();if(!value)return;addTutorMessage(value,'user');$('tutor-input').value='';busy('tutor-send',true,'Thinking...');try{const d=await jsonFetch('/api/tutor',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mensaje:value,categoria:tutorCategory,history:Array.from($('tutor-messages').querySelectorAll('.msg')).slice(-8).map(m=>({role:m.classList.contains('user')?'user':'assistant',content:m.textContent}))})});addTutorMessage(d.respuesta||'Let’s keep practicing.','ai');state.lastTutor=d.respuesta||'';if(settingsAutoplay)speak(d.respuesta||'')}catch(e){toast(e.message)}finally{busy('tutor-send',false,'Send')}}
function tutorMic(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)return toast('Voice input is not available in this browser.');const r=new SR();r.lang='en-US';r.interimResults=false;r.maxAlternatives=1;r.onstart=()=>toast('Listening...');r.onerror=e=>toast('Voice input: '+e.error);r.onresult=e=>tutorSend(e.results[0][0].transcript);r.start()}
async function loadProgress(){try{const d=await jsonFetch('/api/progreso');$('p-total').textContent=d.total_actividades??0;$('p-pron').textContent=d.pronunciacion??0;$('p-writing').textContent=d.escritura??0;$('p-reading').textContent=d.lectura??0;const scores=d.puntuaciones_recientes||[];$('progress-bars').innerHTML=scores.map(x=>`<div class="barcol" title="${Math.round(x)}"><i style="height:${Math.max(4,Math.min(100,Number(x)||0))}%"></i></div>`).join('')||'<div class="empty">No scores yet.</div>';const h=await jsonFetch('/obtener-historial');renderHistory(h)}catch(e){toast(e.message)}}
async function renderPronTrend(){const box=$('pron-trend');if(!box)return;try{const h=await jsonFetch('/obtener-historial');const items=Array.isArray(h)?h:(h.historial||[]);const rows=items.filter(x=>(x.tipo||x.type)==='pronunciation'&&(x.puntuacion??x.score)!=null);const todayStr=new Date().toDateString();const yestStr=new Date(Date.now()-86400000).toDateString();let today='—',yesterday='—',best=0;rows.forEach(r=>{const val=Math.round(Number(r.puntuacion??r.score));const d=new Date(r.created_at||r.fecha||'');const dStr=isNaN(d)?'':d.toDateString();if(dStr===todayStr&&today==='—')today=val;if(dStr===yestStr&&yesterday==='—')yesterday=val;if(val>best)best=val});box.innerHTML=`<div class="pbox"><strong>${today}${today!=='—'?'%':''}</strong><small>Today</small></div><div class="pbox"><strong>${yesterday}${yesterday!=='—'?'%':''}</strong><small>Yesterday</small></div><div class="pbox"><strong>${best}%</strong><small>Best</small></div>`}catch(e){box.innerHTML=''}}
