async function loadNextStep(){
  const t=$('home-next-title'),l=$('home-next-label');if(!t||!l)return;
  try{
    const d=await jsonFetch('/api/learning-path');const units=d.units||[];
    const unit=units.find(u=>u.unlocked&&!u.completed)||units.find(u=>u.unlocked)||units[0];
    if(!unit)throw new Error('none');
    const det=await jsonFetch('/api/learning-path/'+unit.code);
    const topic=(det.topics||[]).find(x=>!x.completed)||(det.topics||[])[0];
    state.next={unit:unit.code,topic:topic?topic.id:null};
    l.textContent='Continue · '+(unit.completed_topics||0)+'/'+(unit.total_topics||0)+' lessons';
    t.textContent=((unit.icon||'')+' '+(unit.title||'')+(topic?' — '+topic.title:'')).trim();
  }catch(e){state.next=null;l.textContent='Next step';t.textContent='Start with a free practice'}
}
async function continueLearning(){
  if(!state.next){section('pronunciacion');return}
  section('learning-path');
  try{await openLearningUnit(state.next.unit);if(state.next.topic)await openLearningTopic(state.next.topic)}catch(e){toast(e.message)}
}
