/* --- repaso espaciado (se guarda en este dispositivo) --- */
const SRS_DAYS=[0,1,3,7,14,30];
function srsKey(){return 'talvo_srs_'+((state.user&&state.user.id)||'anon')}
function srsLoad(){try{return JSON.parse(localStorage.getItem(srsKey())||'{}')}catch(e){return {}}}
function srsSave(m){try{localStorage.setItem(srsKey(),JSON.stringify(m))}catch(e){}}
let srsWords=[],srsQueue=[],srsIdx=0;
async function refreshSrs(){
  const cnt=$('srs-count'),btn=$('srs-start');if(!cnt)return;
  try{const d=await jsonFetch('/api/vocabulario');srsWords=d.palabras||[]}catch(e){srsWords=[]}
  const m=srsLoad(),now=Date.now();
  srsQueue=srsWords.filter(w=>{const r=m[w.id];return !r||r.due<=now});
  if($('srs-session').style.display==='block')return;
  if(srsQueue.length){cnt.textContent=srsQueue.length+(srsQueue.length===1?' word due today':' words due today');btn.style.display=''}
  else{cnt.textContent=srsWords.length?'Nothing to review right now':'Save words from your readings and daily list to review them here.';btn.style.display='none'}
}
function srsShow(){
  const w=srsQueue[srsIdx];if(!w){srsFinish();return}
  $('srs-word').textContent=w.palabra||'';$('srs-meaning').textContent='';
  $('srs-reveal-row').style.display='flex';$('srs-grade-row').style.display='none';
  $('srs-pos').textContent=(srsIdx+1)+' / '+srsQueue.length;
  $('srs-fill').style.width=Math.round(srsIdx/srsQueue.length*100)+'%';
}
function srsFinish(){
  $('srs-session').style.display='none';
  $('srs-count').textContent='Review done!';$('srs-start').style.display='none';
  toast('Come back tomorrow for more.');
}
function srsGrade(g){
  const w=srsQueue[srsIdx];if(!w)return;
  const m=srsLoad(),r=m[w.id]||{box:w.aprendida?2:0};
  const box=g==='again'?0:Math.min(5,r.box+(g==='easy'?2:1));
  m[w.id]={box,due:g==='again'?Date.now()+10*60*1000:Date.now()+SRS_DAYS[box]*86400000};
  srsSave(m);
  if(g==='again')srsQueue.push(w);
  srsIdx++;srsShow();
}
$('srs-start')?.addEventListener('click',()=>{srsIdx=0;$('srs-session').style.display='block';$('srs-start').style.display='none';srsShow()});
$('srs-reveal')?.addEventListener('click',()=>{const w=srsQueue[srsIdx];if(!w)return;$('srs-meaning').textContent=w.significado||'';$('srs-reveal-row').style.display='none';$('srs-grade-row').style.display='flex'});
$('srs-hear')?.addEventListener('click',()=>{const w=srsQueue[srsIdx];if(w)speak(w.palabra)});
$$('#srs-grade-row [data-grade]').forEach(b=>b.addEventListener('click',()=>srsGrade(b.dataset.grade)));

