/* --- llamada manos libres (detecta cuándo hablas y cuándo haces pausa) --- */
const vad={on:false,stream:null,ctx:null,an:null,raf:0,buf:null,floor:0.01,calib:[],voice:0,last:0,started:0,rec:false,starting:false,cool:0,wasBusy:false};
function setHF(on){const b=$('call-handsfree');if(!b)return;b.setAttribute('aria-pressed',on?'true':'false');b.textContent=on?'Hands-free: On':'Hands-free: Off';b.classList.toggle('primary',on);$('call-status').textContent=on?'Listening… speak and pause when you are done.':'Mantén presionado el botón para hablar'}
async function vadStart(){
  if(vad.on)return;
  if(!navigator.mediaDevices?.getUserMedia)return toast('Your browser does not support microphone recording.');
  try{vad.stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}})}catch(e){return toast('Microphone error: '+e.message)}
  const AC=window.AudioContext||window.webkitAudioContext;
  vad.ctx=new AC();vad.an=vad.ctx.createAnalyser();vad.an.fftSize=1024;
  vad.ctx.createMediaStreamSource(vad.stream).connect(vad.an);vad.buf=new Float32Array(vad.an.fftSize);
  vad.on=true;vad.calib=[];vad.voice=0;vad.rec=false;vad.starting=false;vad.cool=performance.now()+600;
  setHF(true);vadLoop();
}
function vadStop(){
  if(!vad.on)return;
  vad.on=false;cancelAnimationFrame(vad.raf);
  try{vad.stream&&vad.stream.getTracks().forEach(t=>t.stop())}catch(e){}
  try{vad.ctx&&vad.ctx.close()}catch(e){}
  vad.stream=null;vad.ctx=null;setHF(false);
}
function vadLoop(){
  if(!vad.on)return;
  vad.raf=requestAnimationFrame(vadLoop);
  vad.an.getFloatTimeDomainData(vad.buf);
  let sum=0;for(let i=0;i<vad.buf.length;i++)sum+=vad.buf[i]*vad.buf[i];
  const rms=Math.sqrt(sum/vad.buf.length),now=performance.now();
  if(state.callBusy){vad.voice=0;vad.wasBusy=true;return}
  if(vad.wasBusy){vad.wasBusy=false;vad.cool=now+900;$('call-status').textContent='Listening… speak and pause when you are done.'}
  if(vad.calib.length<40){vad.calib.push(rms);if(vad.calib.length===40)vad.floor=vad.calib.reduce((a,b)=>a+b,0)/40;return}
  const thr=Math.max(vad.floor*3,0.025),talking=$('call-talk-btn').classList.contains('recording');
  if(rms>thr){
    vad.voice++;vad.last=now;
    if(!talking&&!vad.rec&&!vad.starting&&now>vad.cool&&vad.voice>=8){
      vad.rec=true;vad.starting=true;vad.started=now;
      callStartTalk().then(()=>{$('call-status').textContent='Listening… speak and pause when you are done.'}).finally(()=>{vad.starting=false});
    }
  }else if(talking){
    if(vad.rec&&now-vad.last>1400&&now-vad.started>900){vad.rec=false;vad.voice=0;vad.cool=now+1200;callStopTalk()}
  }else if(!vad.starting){vad.voice=0;vad.rec=false}
}
$('call-handsfree')?.addEventListener('click',()=>vad.on?vadStop():vadStart());

/* --- prueba de nivel en el onboarding --- */
const LEVEL_QS=[
 {q:'She ___ a student.',o:['is','are','am'],a:0},
 {q:'I ___ coffee every morning.',o:['drink','drinks','drinking'],a:0},
 {q:'Yesterday we ___ to the market.',o:['go','went','gone'],a:1},
 {q:"There isn't ___ milk left.",o:['any','some','a'],a:0},
 {q:'If I ___ more time, I would travel more.',o:['have','had','will have'],a:1},
 {q:'She has lived here ___ 2019.',o:['for','since','from'],a:1},
 {q:'By the time we arrived, the movie ___.',o:['already started','has already started','had already started'],a:2},
 {q:'I wish I ___ that job offer last year.',o:['accepted','had accepted','would accept'],a:1}
];
let lvIdx=0,lvScore=0;
function lvShow(){
  const it=LEVEL_QS[lvIdx];
  $('ob-test-count').textContent='Question '+(lvIdx+1)+' of '+LEVEL_QS.length;
  $('ob-test-fill').style.width=Math.round(lvIdx/LEVEL_QS.length*100)+'%';
  $('ob-test-q').textContent=it.q;
  const opts=it.o.map((t,i)=>({t,i})).sort(()=>Math.random()-.5);
  $('ob-test-options').innerHTML=opts.map(x=>'<button type="button" class="ob-option" data-i="'+x.i+'" data-i18n-skip>'+esc(x.t)+'</button>').join('');
}
function lvFinish(){
  const lvl=lvScore<=2?'beginner':lvScore<=4?'elementary':lvScore<=6?'intermediate':'advanced';
  const name={beginner:'Beginner',elementary:'Elementary',intermediate:'Intermediate',advanced:'Advanced'}[lvl];
  obAnswers.cefr_level=lvl;
  $('ob-result-title').textContent='Your level: '+name;
  $('ob-result-text').textContent='You got '+lvScore+' of '+LEVEL_QS.length+' right. You can keep practicing and we adjust as you go.';
  showObStep(5);
}
$('ob-start-test')?.addEventListener('click',()=>{lvIdx=0;lvScore=0;showObStep(4);lvShow()});
$('ob-test-options')?.addEventListener('click',e=>{
  const b=e.target.closest('.ob-option');if(!b)return;
  if(Number(b.dataset.i)===LEVEL_QS[lvIdx].a)lvScore++;
  lvIdx++;if(lvIdx>=LEVEL_QS.length)lvFinish();else lvShow();
});
